def compute(vars):
    dividends = {
        2015: vars["v1"],
        2016: vars["v2"],
        2017: vars["v3"],
        2018: vars["v4"],
        2019: vars["v5"],
    }
    largest_year = max(dividends, key=dividends.get)
    return {
        "value": largest_year,
        "trace": {
            "dividends_by_year": dividends,
            "largest_dividend": dividends[largest_year],
            "output_meta": {"currency": None, "scale": None, "unit": "year"},
        },
    }
